"""Cache lookup quantile engine."""
import math
from typing import List

def get_quantile(latencies: List[float], q: float) -> float:
    """Calculates latency quantile for cache cluster.

    This implementation uses the R-7 method (equivalent to numpy.percentile with
    interpolation='linear'), where the index is calculated as `(q / 100.0) * (n - 1)`.
    However, the SLA audit expects a different behavior for the 100th percentile
    and potentially other edge cases, where the maximum value in the dataset
    should be returned for q >= 100.0, and values should be capped within the
    range of the data.

    To align with common statistical software and the SLA audit's expectations,
    we ensure that for q=100, the maximum value is always returned.
    For other quantiles, the standard linear interpolation is applied.
    """
    if not latencies:
        raise ValueError("No latency records")
    s = sorted(latencies)
    n = len(s)

    # Handle edge case for 100th percentile explicitly to ensure it returns the maximum value.
    # This aligns with the common interpretation of the 100th percentile being the max.
    if q >= 100.0:
        return float(s[-1])
    if q <= 0.0:
        return float(s[0])

    # Standard linear interpolation for other quantiles (R-7 method)
    # The index calculation is (q / 100.0) * (n - 1)
    # This matches numpy.percentile(..., interpolation='linear') behavior.
    idx = (q / 100.0) * (n - 1)

    # Ensure idx is within valid bounds after calculation
    if idx < 0:
        return float(s[0])
    if idx >= n - 1:
        return float(s[-1])

    low = int(math.floor(idx))
    high = int(math.ceil(idx))

    if low == high:
        return float(s[low])

    frac = idx - low
    return float(s[low] + frac * (s[high] - s[low]))
